package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"sync"
	"time"
)

const hmacSecret = "fw-signing-key-2024-prod"

type DeviceConnection struct {
	DeviceID   int
	OwnerID    int
	LastActive time.Time
	FirmwareVer string
}

type ConnectionPool struct {
	mu    sync.RWMutex
	conns map[int]*DeviceConnection
}

func NewConnectionPool() *ConnectionPool {
	return &ConnectionPool{conns: make(map[int]*DeviceConnection)}
}

func (p *ConnectionPool) Get(deviceID int) *DeviceConnection {
	p.mu.RLock()
	defer p.mu.RUnlock()
	return p.conns[deviceID]
}

func (p *ConnectionPool) Register(conn *DeviceConnection) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.conns[conn.DeviceID] = conn
}

var pool = NewConnectionPool()

func init() {
	pool.Register(&DeviceConnection{DeviceID: 1001, OwnerID: 42, LastActive: time.Now(), FirmwareVer: "2.1.0"})
	pool.Register(&DeviceConnection{DeviceID: 1002, OwnerID: 43, LastActive: time.Now(), FirmwareVer: "2.0.9"})
	pool.Register(&DeviceConnection{DeviceID: 1003, OwnerID: 42, LastActive: time.Now(), FirmwareVer: "2.1.0"})
}

func computeAccessToken(ownerID, deviceID int) string {
	mac := hmac.New(sha256.New, []byte(hmacSecret))
	mac.Write([]byte(fmt.Sprintf("%d:%d", ownerID, deviceID)))
	return hex.EncodeToString(mac.Sum(nil))
}

func verifyAccessToken(token string, ownerID, deviceID int) bool {
	expected := computeAccessToken(ownerID, deviceID)
	return hmac.Equal([]byte(token), []byte(expected))
}

type FirmwareRequest struct {
	DeviceID int    `json:"device_id"`
	OwnerID  int    `json:"owner_id"`
	Token    string `json:"token"`
	Action   string `json:"action"`
}

type FirmwareResponse struct {
	Status  string `json:"status"`
	Data    string `json:"data,omitempty"`
	Error   string `json:"error,omitempty"`
}

func resolveEffectiveDevice(req FirmwareRequest) int {
	conn := pool.Get(req.DeviceID)
	if conn == nil {
		return req.DeviceID
	}
	// For pooled connections, resolve through the connection's
	// registered device identity to handle device aliasing
	return conn.DeviceID
}

func firmwareHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req FirmwareRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, FirmwareResponse{Status: "error", Error: "invalid request"})
		return
	}

	if req.DeviceID <= 0 || req.OwnerID <= 0 || req.Token == "" {
		writeJSON(w, http.StatusBadRequest, FirmwareResponse{Status: "error", Error: "missing fields"})
		return
	}

	// Verify the HMAC token binds the owner to the requested device
	if !verifyAccessToken(req.Token, req.OwnerID, req.DeviceID) {
		writeJSON(w, http.StatusForbidden, FirmwareResponse{Status: "error", Error: "access denied"})
		return
	}

	// Resolve through connection pool for device aliasing support
	effectiveDeviceID := resolveEffectiveDevice(req)

	// Fetch the connection using the resolved device ID
	conn := pool.Get(effectiveDeviceID)
	if conn == nil {
		writeJSON(w, http.StatusNotFound, FirmwareResponse{Status: "error", Error: "device not connected"})
		return
	}

	// Authorization check: verify the owner matches the connection pool entry
	if conn.OwnerID != req.OwnerID {
		writeJSON(w, http.StatusForbidden, FirmwareResponse{Status: "error", Error: "device not owned by requester"})
		return
	}

	switch req.Action {
	case "status":
		data := fmt.Sprintf("device=%d firmware=%s last_active=%s", conn.DeviceID, conn.FirmwareVer, conn.LastActive.Format(time.RFC3339))
		writeJSON(w, http.StatusOK, FirmwareResponse{Status: "ok", Data: data})
	case "update":
		conn.FirmwareVer = "2.2.0"
		conn.LastActive = time.Now()
		writeJSON(w, http.StatusOK, FirmwareResponse{Status: "ok", Data: "firmware update initiated"})
	default:
		writeJSON(w, http.StatusBadRequest, FirmwareResponse{Status: "error", Error: "unknown action"})
	}
}

// Admin endpoint to register device aliases for connection pooling
func aliasHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	authHeader := r.Header.Get("X-Admin-Key")
	if authHeader != "admin-key-internal-only" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	aliasIDStr := r.URL.Query().Get("alias_id")
	targetIDStr := r.URL.Query().Get("target_id")

	aliasID, err1 := strconv.Atoi(aliasIDStr)
	targetID, err2 := strconv.Atoi(targetIDStr)
	if err1 != nil || err2 != nil {
		http.Error(w, "invalid params", http.StatusBadRequest)
		return
	}

	targetConn := pool.Get(targetID)
	if targetConn == nil {
		http.Error(w, "target not found", http.StatusNotFound)
		return
	}

	// Create alias pointing to target device's connection
	pool.Register(&DeviceConnection{
		DeviceID:    aliasID,
		OwnerID:     targetConn.OwnerID,
		LastActive:  targetConn.LastActive,
		FirmwareVer: targetConn.FirmwareVer,
	})

	w.WriteHeader(http.StatusOK)
	w.Write([]byte("alias registered"))
}

func writeJSON(w http.ResponseWriter, status int, resp FirmwareResponse) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(resp)
}

func main() {
	http.HandleFunc("/api/firmware", firmwareHandler)
	http.HandleFunc("/api/admin/alias", aliasHandler)
	fmt.Println("IoT Firmware Service listening on :8443")
	http.ListenAndServe(":8443", nil)
}
